"""Editorial mapping of annotated pairs to classic relation semantics."""
import json,collections
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parent
read=lambda p:json.loads(p.read_text())
deck=read(R/'working-deck/deck.json')
edges=sorted({tuple(sorted((c['word'],v))) for c in deck['playable_cards'] for v in c['playable_partners']})
assert len(edges)==106
# Row numbers refer to the sorted 106-pair snapshot; assertions detect input drift.
assert edges[0]==('безнадёжность','надежда') and edges[-1]==('улыбка','умиление')
groups={
'Противоположность':[1,3,5,8,10,11,15,19,22,31,40,54,58,62,78,80,83,95,100,104],
'Проявление (нет отдельного старого типа)':[13,14,16,17,24,25,27,28,33,34,35,37,38,42,47,48,49,50,51,52,53,55,57,72,74,84,85,86,93,94,97,98,101,102,106],
'Свойство':[6,7],
'Часть / составляющая':[18,21,32,45,61,75,82,96],
'Вид':[4,9,12,20,23,26,30,36,39,41,43,44,46,56,60,63,64,65,66,67,68,69,70,71,73,76,77,79,81,87,88,89,90,91,92,99,105],
'Объект переживания':[29,103],
'Ослабление состояния':[59],
'Требует пересмотра исходной пары':[2]}
flat=[i for ids in groups.values() for i in ids];assert sorted(flat)==list(range(1,107))
ix={i:g for g,ids in groups.items() for i in ids}
source={(e['a'],e['b']):e['evidence'] for e in read(R/'bridge-audit/reviewed-graph.json')}
classifications=[]
for fn in ['central-concepts/classification.json','central-concepts-v2/classification.json']:classifications+=read(R/fn)
records=[]
for i,(a,b) in enumerate(edges,1):
 ev=[e for e in source.get((a,b),[]) if e['grade']==2]
 if not ev:
  ev=[dict(type=r['relation'],explanation=r['explanation']) for r in classifications if ((r['center']==a and r['representative']==b) or (r['center']==b and r['representative']==a)) and r.get('score',r.get('grade'))==2][:1]
 assert ev,(a,b)
 caveat=''
 if i==2:caveat='Общее отсутствие надежды не доказывает, что одно переживание является частью другого. Старую степень 2 следует отдельно перепроверить.'
 if i==26:caveat='Сопоставление по интенсивности условно: не всякий гнев является усилением раздражения. Отнесение к виду предварительное.'
 if i==81:caveat='Раздражение как форма неудовольствия — широкая редакторская классификация, требует подтверждения при проверке смыслов.'
 if i in [6,7]:caveat='Безутешность может рассматриваться и как состояние; трактовка свойством зависит от выбранного объяснения.'
 records.append(dict(a=a,b=b,primary_relation=ix[i],evidence=ev,caveat=caveat))
neutral=[]
for c in deck['playable_cards']:
 for center in c['neutral_partners']:
  rs=[r for r in classifications if r['center']==center and r['representative']==c['word'] and r.get('score',r.get('grade'))==2]
  kind=rs[0]['relation'] if rs else 'форма/содержание'
  assert rs or (c['word'],center)==('ощущение','состояние')
  neutral.append(dict(card=c['word'],center=center,classification=kind))
counts={g:len(v) for g,v in groups.items()};counts['Причина']=0
summary=dict(scope='106 известных внутренних пар и 198 известных пар с нейтральными. Не все возможные пары колоды.',internal_counts=counts,neutral_counts=dict(collections.Counter(x['classification'] for x in neutral)),classic_provisional_coverage=67,missing_manifestation=35,other_or_questionable=4)
assert len(neutral)==198
for name,data in [('pairs.json',records),('neutral-pairs.json',neutral),('summary.json',summary)]: (P/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
lines=['# Аудит классических типов связей','', 'Источник правил: game-rules.md, раздел 5. Анализируется утверждённый рабочий состав: 57 игральных и 5 нейтральных карт. Правила игры и состав не изменены.','', '## Вывод','', 'Набор частично подходит. Вид и противоположность востребованы; часть применима как составляющая переживания; свойство встречается редко. Главный пробел — проявление: выражение эмоции жестом, голосом или телесным признаком. Причинность остаётся возможной, но её нельзя выводить автоматически из выражения или совместного появления.','', '## Внутренние пары','', '| Основное отношение | Пар |','|---|---:|']
for g,n in counts.items():lines.append(f'| {g} | {n} |')
lines+=['', 'Для каждой пары выбрано одно основное отношение, чтобы суммы не раздувались. Это редакторская раскладка, не запрет нескольких убедительных объяснений. В старые пять типов предварительно укладываются 67 из 106 пар (63,2%); 35 требуют отдельного проявления, ещё четыре имеют иную природу или сомнительное исходное обоснование. Две пары вида дополнительно отмечены как спорные. Число 67 не является числом независимо подтверждённых пар.','', 'Ноль у причины означает, что в уже принятом строгом списке нет пары с причинностью как основным обоснованием. Это НЕ означает отсутствие возможных причинных ходов. Исходный аудит намеренно оставлял многие причинные предположения на контекстном уровне; по этому графу нельзя сравнивать реальную частоту типов в игре.','', '## Нейтральные карты','', 'Отдельно учтены 198 известных пар с пятью нейтральными: 160 размечены как форма/содержание и 38 — как выражение. Первые являются кандидатами на вид или составляющую, но прежняя метка сама по себе не доказывает конкретный тип. Вторые подтверждают, что отсутствие типа проявления влияет и на стартовые ходы. Десять ещё не проверенных пар перенесённых настроения/отношения с центрами сюда не включены.','', '## Рекомендуемый набор для первой проверки','', '| Тип | Короткое правило | Направление и пример |','|---|---|---|',
'| Вид | Первое — разновидность второго | Ужас → Страх |',
'| Составляющая (уточнение «Части») | Первое входит в состав второго | Напряжение → Тревога |',
'| Причина | Первое может вызвать второе; игрок объясняет механизм и ситуацию | Усталость → Раздражение, контекстный пример, не добавленный в строгий граф |',
'| Свойство | Первое характеризует второе | Безутешность → Горе; редкая и спорная трактовка |',
'| Противопоставление | Общий признак, по которому понятия противопоставлены | Бодрость ↔ Усталость |',
'| Проявление — новый тип | Первое может выражать или проявлять второе | Улыбка → Радость; Дрожь → Страх |',
'', 'Для первой проверки предложены шесть типов: сохраняются возможности старых пяти и добавляется недостающее проявление. Название «Часть» можно уточнить в подсказке без изменения направления. Направление нового проявления выбрано от выражения к выражаемому; это отдельная предлагаемая договорённость, ещё не правило игры. Направления существующих типов не разворачиваются. Симметричным остаётся только противопоставление.','', 'Не стоит подгонять улыбку под свойство радости, а страх автоматически объявлять причиной любого крика. Проявление описывает выражение, причина — возникновение. Один пример может допускать оба объяснения, но они не тождественны. Наличие проявления не является диагнозом или однозначным признаком чувства.','', '## Остаточные случаи','', '- Горе — Сострадание и Страдание — Сострадание: объект чужого переживания. Это не автоматически часть или вид. Причинное объяснение возможно только отдельной проверкой, пока его не засчитываем.','- Напряжение — Облегчение: ослабление состояния. Можно в будущем проверить тип «Ослабляет», но одной пары недостаточно для обязательного отдельного типа.','- Безнадёжность — Отчаяние: прежнее объяснение указывает на общую утрату надежды, а не доказывает включение. Нужен пересмотр самой пары.','', '## Что делать дальше','', 'Рекомендация: проверить шеститипный набор на объяснениях пар, затем пересчитать граф с учётом только подходящих типов. Нельзя обещать сохранить прежние 106 допустимых пар и минимум два партнёра: текущая колода отбиралась до фиксации типов. Например, безнадёжность может потерять второго партнёра при исключении спорной пары с отчаянием. Не добавлять типы только для спасения конкретной карты.','', '## Полная раскладка','', '| Пара | Основное отношение | Ограничение |','|---|---|---|']
for r in records:lines.append(f"| {r['a']} — {r['b']} | {r['primary_relation']} | {r['caveat']} |")
lines+=['', 'Воспроизведение: `python docs/deck-research/emotions-ru/relation-types-audit/build.py`. pairs.json сохраняет объяснения и оговорки каждой пары. Это аудит текущих аннотаций; словарное исследование заново не выполнялось.']
(P/'README.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(summary,ensure_ascii=False))
